      "releaseTag": "Release notes",
      "releaseTitle": "A bigger home for every WalkQuest journey",
      "releaseLead": "The new WalkQuest website is more than a landing page: it is now a multilingual field guide for understanding the game before your first step.",
      "releaseDate": "October 1, 2026",
      "releaseReadTime": "6 min read",
      "releaseIntroP1": "A walking game can be simple to play and still contain a whole world of details. WalkQuest connects steps, routes, cities, transfers, passport stamps, achievements, and Premium options. The redesigned website brings those pieces together in one calm place.",
      "releaseIntroP2": "The goal is practical: a visitor should understand what WalkQuest does in less than a minute, while an active traveller can find a deeper answer without searching through menus.",
      "releaseLanguageTitle": "Sixteen languages, one shared journey",
      "releaseLanguageP1": "Every main page and every article follows the language selected on the site. On a first visit, WalkQuest checks the browser language; if it is supported, the page opens in that language automatically. Otherwise, English is used.",
      "releaseLanguageP2": "The choice is saved on the device and follows you from the game guide to routes, Premium, privacy, and the journal. Arabic also changes the complete reading direction to right-to-left.",
      "releaseCalloutTitle": "Why this matters",
      "releaseCalloutText": "A player arriving directly from Google Play can read the explanation, privacy policy, and support material in a familiar language without creating an account.",
      "releasePathTitle": "A clearer path from curiosity to the first walk",
      "releasePathP1": "The website now separates quick answers from detailed guidance. The home page explains the promise; the game guide shows the controls; the route atlas helps choose a destination; the Premium page explains purchases without hiding the free experience.",
      "releaseFeature1Title": "Game guide",
      "releaseFeature1Text": "See how steps move the marker, how cities unlock, and what happens at a ferry, train, or flight gate.",
      "releaseFeature2Title": "Route atlas",
      "releaseFeature2Text": "Compare short adventures with epic journeys using real distances, stops, difficulty, and transfer counts.",
      "releaseFeature3Title": "Journal",
      "releaseFeature3Text": "Read focused stories about releases, destinations, and practical setup instead of vague marketing announcements.",
      "releaseSameTitle": "What has not changed",
      "releaseSameP1": "WalkQuest still does not require an account. Step access remains read-only and permission-based. Your real movement becomes progress on the route you choose, while the website remains a lightweight static site with no sign-in wall.",
      "releaseQuote": "The website should feel like the first page of a travel journal: useful before the journey and worth returning to after it begins.",
      "releaseNextTitle": "What comes next",
      "releaseNextP1": "Future notes will explain meaningful changes in plain language: what changed, why it changed, and whether it affects existing progress. Route spotlights and practical guides will continue alongside them.",
