      "europeTag": "Route spotlight",
      "europeTitle": "WalkQuest Europe Explorer: 1,240 km from London to Prague",
      "europeLead": "Twelve city stops, six countries, and one free route designed to turn an ordinary walking habit into a continental adventure.",
      "europeDate": "October 1, 2026",
