      "europeStatCountries": "countries",
      "europeStatWeeksValue": "8–10 weeks",
      "europeStatWeeks": "estimated journey",
      "europeIntroP1": "Europe Explorer is the route we recommend when somebody asks, “Where should I begin?” It is long enough to feel like a real expedition, varied enough to keep the map interesting, and available without a Premium purchase.",
      "europeIntroP2": "The journey begins in London and moves east toward Prague. Along the way, each reached city becomes more than a dot: it opens a story, local facts, landmarks, food, map links, and a new passport stamp.",
      "europeWhyTitle": "Why it works as a first route",
      "europeWhyP1": "The Easy difficulty is not about making the kilometres disappear. It means the route has a friendly rhythm and an understandable goal. At roughly 1,250 steps per virtual kilometre before bonuses, even a modest daily walk produces visible progress.",
      "europeCalloutTitle": "A useful pace",
      "europeCalloutText": "Do not chase the finish line on day one. Pick a daily walking target you can repeat, then let the cities arrive as rewards for consistency.",
      "europeStopsTitle": "The pleasure is between the famous landmarks",
      "europeStopsP1": "London, Paris, alpine scenery, historic streets, and Prague provide the big postcard moments. The quieter transitions matter too: watching the marker leave one city, cross a border, and approach the next destination gives an ordinary week a sense of direction.",
      "europeStopsP2": "When a stop unlocks, pause for a minute. Read the short introduction, open a landmark, look at Street View when it is available, and add the stamp to your passport. That small ritual is what turns distance into a journey.",
      "europeRoutineTitle": "Make the route fit your real life",
      "europeStep1Title": "Choose a repeatable baseline.",
      "europeStep1Text": "A twenty-minute walk you actually take is more valuable than an ambitious plan you abandon.",
      "europeStep2Title": "Check the next city, not the final kilometre.",
      "europeStep2Text": "Short targets make a 1,240 km route feel inviting instead of overwhelming.",
      "europeStep3Title": "Use the story as the reward.",
      "europeStep3Text": "Open the city card after arrival and give yourself time to explore what you unlocked.",
      "europeFinishTitle": "What happens at the finish",
      "europeFinishP1": "Completing Europe Explorer gives you a finished route, a record of every reached city, and the confidence to choose a more demanding world next. Italy, Japan, Iceland, Greek islands, Route 66, and global journeys are waiting when you want a different rhythm.",
      "europeQuote": "The best route is not the longest one. It is the route that makes tomorrow’s walk feel worth taking.",
      "europeNextLink": "Connect Health Connect without guesswork →",
      "europeHeroAlt": "Illustrated walking route through London, Paris, the Alps, and Prague",
      "healthTag": "Practical guide",
      "healthTitle": "WalkQuest Health Connect setup without guesswork",
      "healthLead": "A calm step-by-step guide to permissions, synchronization, and the small checks that solve most missing-step problems.",
      "healthDate": "October 1, 2026",
      "healthReadTime": "8 min read",
      "healthIntroP1": "WalkQuest does not count movement by keeping a permanent tracker running in the background. It reads the step totals already collected through Android Health Connect, after you grant permission. That keeps the connection understandable and under your control.",
      "healthStatReadOnlyValue": "Read only",
      "healthStatReadOnly": "step permission",
