      "healthStep2Title": "Allow step access.",
      "healthStep2Text": "Approve read access for steps. WalkQuest does not need permission to change your health records.",
      "healthStep3Title": "Return and synchronize.",
      "healthStep3Text": "Go back to WalkQuest, refresh the step data, and check that the route marker advances.",
      "healthCalloutTitle": "Good to know",
      "healthCalloutText": "Your phone or wearable may write steps to Health Connect with a short delay. A delayed update is not necessarily lost progress.",
      "healthMissingTitle": "If the number does not move",
      "healthMissingP1": "Start with the simplest checks. Open Health Connect and confirm that step data exists for today. Then verify that WalkQuest still has permission to read it. Battery restrictions, a newly installed health app, or moving to a different phone can change the connection.",
      "healthCheck1": "Confirm that your step source is writing data to Health Connect.",
      "healthCheck2": "Check WalkQuest permissions inside Health Connect.",
      "healthCheck3": "Open WalkQuest with an internet connection and trigger synchronization again.",
      "healthCheck4": "Check the selected date and remember that today’s total can update in batches.",
      "healthCheck5": "After reinstalling, reconnect Health Connect before expecting old steps to appear.",
      "healthDistanceTitle": "Why steps and kilometres are not identical",
      "healthDistanceP1": "WalkQuest uses a simple game conversion of approximately 1,250 steps for one virtual kilometre before bonuses and other modifiers. It is a motivational game distance, not a medical measurement of stride length.",
      "healthDistanceP2": "That means two apps can show different kilometre values while agreeing on the same number of steps. For WalkQuest, the step total is the important input; the route distance is the game’s interpretation of that effort.",
