      "routesPageDescription": "Відкрийте для себе 30 віртуальних подорожей WalkQuest із 303 зупинками в містах від Європи та Кіото до Ісландії, Патагонії та Route 66.",
      "premiumPageTitle": "Premium | WalkQuest",
