      "healthDistanceTitle": "Почему данные о шагах и километрах различаются",
      "healthDistanceP1": "WalkQuest использует простой игровой алгоритм пересчета: примерно 1250 шагов на один виртуальный километр (без учета бонусов и других модификаторов). Это игровая дистанция для мотивации, а не медицинский показатель длины шага.",
