      "news1Title": "WalkQuest dispose désormais d'une maison multilingue sur le Web",
      "news1Text": "La page de destination, la politique de confidentialité, le guide du jeu, l'atlas des itinéraires, le guide Premium et les actualités sont disponibles en seize langues avec le support RTL arabe.",
      "news2Tag": "Itinéraires",
      "news2Date": "28 septembre 2026",
      "news2Title": "La bibliothèque d'itinéraires atteint une trentaine de trajets",
      "news2Text": "WalkQuest couvre désormais 303 arrêts urbains et 18 transferts en train, ferry ou avion sur des itinéraires allant de Kiev et Kyoto à la Patagonie et à l'Islande.",
      "news3Tag": "Guider",
