      "europeArticlePageTitle": "Itinéraire Europe Explorer | WalkQuest",
      "europeArticlePageDescription": "Découvrez l'itinéraire gratuit Europe Explorer (1 240 km) avec 12 étapes à travers six pays.",
      "healthArticlePageTitle": "Guide Health Connect | WalkQuest",
