      "releaseReadTime": "Tempo de leitura: 6 min",
      "releaseIntroP1": "Um jogo de caminhada pode ser simples de jogar e ainda assim conter um mundo inteiro de detalhes. O WalkQuest liga passos, rotas, cidades, transfers, carimbos no passaporte, conquistas e opções Premium. O site reformulado reúne todos estes elementos num só lugar.",
      "releaseIntroP2": "O objetivo é prático: um visitante deve compreender o que o WalkQuest faz em menos de um minuto, enquanto um viajante ativo pode encontrar respostas mais detalhadas sem ter de navegar por menus.",
