      "europeStatDistance": "Distância total",
      "europeStatStops": "Paragens em cidades",
      "europeStatCountries": "Países",
      "europeStatWeeksValue": "8 a 10 semanas",
      "europeStatWeeks": "Percurso estimado",
      "europeIntroP1": "Explorador da Europa é o percurso que recomendamos quando alguém pergunta: \"Por onde devo começar?\". É longo o suficiente para parecer uma verdadeira expedição, variado o suficiente para manter o mapa interessante e disponível sem a necessidade de comprar uma subscrição Premium.",
      "europeIntroP2": "A viagem começa em Londres e segue para leste, em direção a Praga. Ao longo do caminho, cada cidade alcançada torna-se mais do que um ponto: revela uma história, curiosidades locais, pontos turísticos, gastronomia, links para mapas e um novo carimbo no passaporte.",
      "europeWhyTitle": "Porque funciona como um primeiro percurso",
      "europeWhyP1": "A dificuldade Fácil não se trata de fazer desaparecer os quilómetros. Significa que o percurso tem um ritmo agradável e um objetivo compreensível. Com aproximadamente 1. 250 passos por quilómetro virtual antes dos bónus, mesmo uma caminhada diária modesta produz progressos visíveis.",
      "europeCalloutTitle": "Um ritmo ideal",
      "europeCalloutText": "Não tente cortar a meta no primeiro dia. Escolha um objetivo de caminhada diária que possa repetir e deixe que as cidades surjam como recompensas pela sua consistência.",
      "europeStopsTitle": "O prazer está entre os pontos turísticos famosos.",
      "europeStopsP1": "Londres, Paris, paisagens alpinas, ruas históricas e Praga proporcionam os grandes momentos de postal. As transições mais tranquilas também importam: observar o marcador a sair de uma cidade, atravessar uma fronteira e aproximar-se do próximo destino dá um sentido de direção a uma semana comum.",
      "europeStopsP2": "Quando uma paragem for desbloqueada, pare durante um minuto. Leia a breve introdução, abra um ponto turístico, veja o Street View quando estiver disponível e adicione o carimbo ao seu passaporte. Este pequeno ritual é o que transforma a distância numa viagem.",
      "europeRoutineTitle": "Adapte a rota à sua vida real.",
      "europeStep1Title": "Escolha uma base repetível.",
      "europeStep1Text": "Uma caminhada de vinte minutos que realmente faz é mais valiosa do que um plano ambicioso que abandona.",
      "europeStep2Title": "Verifique a próxima cidade, não o último quilómetro.",
      "europeStep2Text": "Metas curtas tornam uma rota de 1. 240 km convidativa em vez de assustadora.",
      "europeStep3Title": "Use a história como recompensa.",
      "europeStep3Text": "Abra o cartão da cidade após a chegada e dedique algum tempo a explorar o que desbloqueou.",
      "europeFinishTitle": "O que acontece no final?",
      "europeFinishP1": "A conclusão do Explorador da Europa dá-lhe uma rota finalizada, um registo de cada cidade visitada e a confiança para escolher um mundo mais desafiante a seguir. Itália, Japão, Islândia, ilhas gregas, Rota 66 e viagens globais estão à sua espera quando quiser um ritmo diferente.",
      "europeQuote": "A melhor rota não é a mais longa. É o percurso que faz com que a caminhada de amanhã valha a pena.",
      "europeNextLink": "Ligar o Health Connect sem complicações →",
      "europeHeroAlt": "Percurso pedestre ilustrado por Londres, Paris, os Alpes e Praga",
      "healthTag": "Guia prático",
      "healthTitle": "Ligar o Health Connect sem complicações",
      "healthLead": "Um guia passo a passo tranquilo sobre permissões, sincronização e as pequenas verificações que resolvem a maioria dos problemas de passos em falta.",
      "healthDate": "1 de outubro de 2026",
      "healthReadTime": "Tempo de leitura: 8 min",
      "healthIntroP1": "O WalkQuest não contabiliza os movimentos mantendo um rastreador permanente em segundo plano. Lê o total de passos já recolhidos pelo Android Health Connect, após lhe conceder a permissão. Isto mantém a ligação compreensível e sob o seu controlo.",
      "healthStatReadOnlyValue": "Apenas leitura",
      "healthStatReadOnly": "Permissão para passos",
      "healthStatAccountValue": "Sem conta",
      "healthStatAccount": "Necessário",
      "healthStatSteps": "Passos por km de percurso",
      "healthSetupTitle": "Ligue em três etapas",
      "healthStep1Title": "Abra as Definições do WalkQuest.",
      "healthStep1Text": "Encontre a secção Health Connect e inicie a ligação dentro da aplicação.",
      "healthStep2Title": "Permitir o acesso aos passos.",
      "healthStep2Text": "Aprove o acesso de leitura para os passos. O WalkQuest não precisa de permissão para alterar os seus registos de saúde.",
      "healthStep3Title": "Volte e sincronize.",
      "healthStep3Text": "Volte ao WalkQuest, atualize os dados dos passos e verifique se o marcador de percurso avança.",
      "healthCalloutTitle": "Bom saber",
      "healthCalloutText": "O seu telefone ou dispositivo wearable pode gravar os passos no Health Connect com um pequeno atraso. Uma atualização tardia não significa necessariamente perda de progresso.",
      "healthMissingTitle": "Se o número não mudar",
      "healthMissingP1": "Comece pelas verificações mais simples. Abra o Health Connect e confirme se existem dados de passos para o dia de hoje. Em seguida, verifique se o WalkQuest ainda tem permissão para os ler. Restrições de bateria, uma aplicação de saúde recém-instalada ou a troca para um telefone diferente podem afetar a ligação.",
      "healthCheck1": "Confirme se a sua fonte de passos está a gravar dados no Health Connect.",
      "healthCheck2": "Verifique as permissões do WalkQuest no Health Connect.",
      "healthCheck3": "Abra o WalkQuest com uma ligação à internet e inicie novamente a sincronização.",
      "healthCheck4": "Verifique a data selecionada e lembre-se que o total de hoje pode ser atualizado em lotes.",
      "healthCheck5": "Após reinstalar, volte a ligar o Health Connect antes de esperar que os passos antigos apareçam.",
      "healthDistanceTitle": "Porque é que passos e quilómetros não são idênticos",
      "healthDistanceP1": "O WalkQuest utiliza uma conversão simples de jogo, de aproximadamente 1. 250 passos para um quilómetro virtual, antes dos bónus e outros modificadores. É uma distância motivacional do jogo, não uma medição médica do comprimento da passada.",
      "healthDistanceP2": "Isto significa que duas aplicações podem mostrar valores diferentes de quilómetros, mesmo concordando com o mesmo número de passos. Para o WalkQuest, o total de passos é a entrada importante;a distância da rota é a interpretação do jogo deste esforço.",
      "healthPrivacyTitle": "O que o WalkQuest lê — e o que não lê",
      "healthPrivacyP1": "O acesso solicitado está limitado à informação de passos necessária para o progresso da rota. O WalkQuest não requer uma conta e os dados de saúde não são utilizados para criar um perfil de publicidade. Pode revogar o acesso a qualquer momento nas definições do Health Connect.",
      "healthQuote": "Uma boa ligação deve ser silenciosa: conceda permissão uma vez, caminhe normalmente e deixe o seu mapa contar a história.",
      "healthNextLink": "Leia o que mudou no site do WalkQuest →",
      "healthHeroAlt": "Sincronização segura de passos de um serviço de saúde para uma rota do WalkQuest",
