      "newsNext3Text": "Adım erişimini ayarlayın, senkronizasyonu anlayın ve en sık karşılaşılan eksik adım sorunlarını çözün.",
      "newsCtaTitle": "Bir sonraki hikaye bir sonraki yürüyüşünüzle başlar",
