      "healthSetupTitle": "Üç bilinçli adımda bağlantı kurun",
      "healthStep1Title": "WalkQuest Ayarları'nı açın.",
      "healthStep1Text": "Health Connect bölümünü bulun ve bağlantıyı uygulama içinden başlatın.",
      "healthStep2Title": "Adım verilerine erişim izni verin.",
      "healthStep2Text": "Adım verilerini okuma iznini onaylayın. WalkQuest'in sağlık kayıtlarınızı değiştirme iznine ihtiyacı yoktur.",
      "healthStep3Title": "Geri dönün ve senkronize edin.",
      "healthStep3Text": "WalkQuest'e geri dönün, adım verilerini yenileyin ve rota işaretçisinin ilerlediğini kontrol edin.",
      "healthCalloutTitle": "Bilmekte fayda var",
      "healthCalloutText": "Telefonunuz veya giyilebilir cihazınız, adım verilerini Health Connect'e kısa bir gecikmeyle yazabilir. Gecikmeli bir güncelleme, verilerin kaybolduğu anlamına gelmez.",
      "healthMissingTitle": "Sayı değişmiyorsa",
      "healthMissingP1": "En basit kontrollerle başlayın. Health Connect'i açın ve bugüne ait adım verilerinin mevcut olduğunu onaylayın. Ardından, WalkQuest'in bu verileri okuma izninin hâlâ geçerli olduğunu doğrulayın. Pil kısıtlamaları, yeni yüklenen bir sağlık uygulaması veya farklı bir telefona geçiş bağlantıyı etkileyebilir.",
      "healthCheck1": "Adım kaynağınızın Health Connect'e veri yazdığından emin olun.",
      "healthCheck2": "Health Connect içindeki WalkQuest izinlerini kontrol edin.",
      "healthCheck3": "İnternet bağlantısı varken WalkQuest'i açın ve senkronizasyonu yeniden başlatın.",
