      "healthCheck5": "Uygulamayı yeniden yükledikten sonra, eski adımların görünmesini beklemeden önce Health Connect bağlantısını yeniden kurun.",
      "healthDistanceTitle": "Adım ve kilometre değerleri neden birebir aynı değil?",
      "healthDistanceP1": "WalkQuest, bonuslar ve diğer değiştiriciler hesaba katılmadan önce, bir sanal kilometre için yaklaşık 1. 250 adımlık basit bir oyun dönüşümü kullanır. Bu, adım uzunluğuna dayalı tıbbi bir ölçüm değil, motivasyon amaçlı bir oyun mesafesidir.",
      "healthDistanceP2": "Bu durum, iki uygulamanın aynı adım sayısı üzerinde mutabık kalırken farklı kilometre değerleri gösterebileceği anlamına gelir. WalkQuest için önemli olan girdi toplam adım sayısıdır;rota mesafesi ise bu çabanın oyun içindeki karşılığıdır.",
      "healthPrivacyTitle": "WalkQuest neleri okur, neleri okumaz?",
      "healthPrivacyP1": "İstenen erişim, rota ilerlemesi için gerekli olan adım bilgisiyle sınırlıdır. WalkQuest hesap oluşturmanızı gerektirmez ve sağlık verileriniz reklam profili oluşturmak amacıyla kullanılmaz. Erişimi dilediğiniz zaman Health Connect ayarlarından iptal edebilirsiniz.",
      "healthQuote": "İyi bir bağlantı sessizce çalışmalıdır: izni bir kez verin, normal şekilde yürüyün ve hikayeyi haritanız anlatsın.",
      "healthNextLink": "WalkQuest web sitesindeki yenilikleri okuyun →",
