      "healthStatAccount": "必要",
      "healthStatSteps": "ルート1kmあたりの歩数",
      "healthSetupTitle": "3つのステップで確実に接続",
      "healthStep1Title": "WalkQuestの設定を開きます。",
      "healthStep1Text": "「Health Connect」の項目を見つけ、アプリ内から接続を開始します。",
      "healthStep2Title": "歩数データへのアクセスを許可します。",
      "healthStep2Text": "歩数データの読み取りを許可してください。WalkQuestが健康記録を変更する権限を必要とすることはありません。",
      "healthStep3Title": "戻って同期する。",
      "healthStep3Text": "WalkQuestに戻り、歩数データを更新して、ルート上のマーカーが進むことを確認してください。",
      "healthCalloutTitle": "知っておくと役立つ情報",
      "healthCalloutText": "お使いのスマートフォンやウェアラブル端末からHealth Connectへの歩数データの書き込みには、多少の遅延が生じることがあります。更新が遅れても、記録が失われたわけではありません。",
      "healthMissingTitle": "数値が変化しない場合",
      "healthMissingP1": "まずは基本的な確認から始めましょう。Health Connectを開き、本日の歩数データが存在することを確認してください。次に、WalkQuestにそのデータを読み取る権限が維持されているか確認します。バッテリー制限の設定、新しいヘルスケアアプリのインストール、またはスマートフォンの機種変更などが、接続状況に影響を与える可能性があります。",
      "healthCheck1": "歩数データの計測元（ソース）がHealth Connectにデータを書き込んでいるか確認してください。",
      "healthCheck2": "Health Connect内でWalkQuestの権限設定を確認してください。",
      "healthCheck3": "インターネットに接続した状態でWalkQuestを開き、再度同期を行ってください。",
      "healthCheck4": "選択した日付を確認してください。また、本日の合計歩数はまとめて更新される場合がある点にご注意ください。",
      "healthCheck5": "アプリを再インストールした場合は、過去の歩数が表示される前に、Health Connectとの接続を再度行ってください。",
      "healthDistanceTitle": "歩数と距離（キロメートル）が一致しない理由",
      "healthDistanceP1": "WalkQuestでは、ボーナスやその他の補正要素を除き、仮想上の1キロメートルを約1,250歩と換算するシンプルなゲーム内計算式を採用しています。これはあくまでゲーム上の距離であり、歩幅に基づく医学的な測定値ではありません。",
      "healthDistanceP2": "そのため、歩数の数値が同じであっても、アプリによって表示される距離（キロメートル）が異なる場合があります。WalkQuestにおいて重要な入力データは「合計歩数」であり、ルート上の距離はその努力をゲームとして解釈した結果に過ぎません。",
      "healthPrivacyTitle": "WalkQuestが読み取るデータ・読み取らないデータ",
      "healthPrivacyP1": "要求されるアクセス権限は、ルートの進行に必要な歩数情報のみに限定されています。WalkQuestの利用にアカウント登録は不要であり、健康データが広告配信用のプロファイル作成に使用されることもありません。アクセス権限は、Health Connectの設定からいつでも取り消すことができます。",
      "healthQuote": "優れた連携とは、静かなものです。一度許可を与えれば、あとは普通に歩くだけ。地図がその旅の物語を語ってくれます。",
      "healthNextLink": "WalkQuestウェブサイトの変更点を確認する →",
