      "europeStep3Title": "이야기를 보상으로 삼으세요.",
      "europeStep3Text": "목적지에 도착하면 도시 카드를 열어보고, 새롭게 잠금 해제된 내용을 둘러볼 시간을 가져보세요.",
      "europeFinishTitle": "여정을 마친 후에는 어떤 일이 일어날까요?",
      "europeFinishP1": "'유럽 탐험가(Europe Explorer)'를 완료하면 완성된 경로와 방문한 모든 도시의 기록을 얻게 되며, 다음번에는 더 난이도 높은 세계 여행에 도전할 자신감도 생깁니다. 색다른 분위기의 여정을 원하신다면 이탈리아, 일본, 아이슬란드, 그리스 섬, 루트 66, 그리고 세계 일주 여행이 여러분을 기다리고 있습니다.",
      "europeQuote": "최고의 경로는 가장 긴 경로가 아닙니다. 내일의 걷기가 가치 있게 느껴지도록 만드는 경로가 바로 최고의 경로입니다.",
