      "news3Date": "20 سبتمبر 2026",
      "news3Title": "اكتشف المزيد داخل كل مدينة غير مقفلة",
      "news3Text": "افتح قصص المدينة والمعالم والأطعمة المحلية وخرائط Google وStreet View القريبة وطوابع جواز السفر وبطاقات السفر القابلة للمشاركة.",
