      "healthTag": "دليل عملي",
      "healthTitle": "اربط تطبيق Health Connect دون تعقيدات أو تخمينات",
      "healthLead": "دليل هادئ ومبسط خطوة بخطوة حول الأذونات، والمزامنة، والتحقق من الإعدادات البسيطة التي تحل معظم مشاكل عدم احتساب الخطوات.",
      "healthDate": "1 أكتوبر 2026",
      "healthReadTime": "وقت القراءة: 8 دقائق",
      "healthIntroP1": "لا يقوم تطبيق WalkQuest باحتساب الحركة عبر تشغيل أداة تتبع دائمة في الخلفية؛بل يقرأ إجمالي الخطوات التي تم جمعها بالفعل عبر خدمة Android Health Connect، وذلك بعد منحك الإذن بذلك. وهذا يجعل عملية الربط واضحة ومفهومة وتحت سيطرتك الكاملة.",
      "healthStatReadOnlyValue": "للقراءة فقط",
