      "healthCalloutTitle": "معلومات مفيدة",
      "healthCalloutText": "قد يقوم هاتفك أو جهازك القابل للارتداء بتسجيل الخطوات في Health Connect مع تأخير بسيط؛فالتحديث المتأخر لا يعني بالضرورة ضياع التقدم المحرز.",
      "healthMissingTitle": "إذا لم يتغير الرقم",
      "healthMissingP1": "ابدأ بالتحقق من الأمور البسيطة أولاً. افتح تطبيق Health Connect وتأكد من وجود بيانات للخطوات خاصة باليوم الحالي، ثم تحقق من أن WalkQuest لا يزال يمتلك إذن القراءة. قد تؤثر قيود البطارية، أو تثبيت تطبيق صحي جديد، أو الانتقال إلى هاتف آخر على الاتصال.",
      "healthCheck1": "تأكد من أن المصدر الذي يحسب خطواتك يقوم بكتابة البيانات في Health Connect.",
      "healthCheck2": "تحقق من أذونات WalkQuest داخل تطبيق Health Connect.",
      "healthCheck3": "افتح تطبيق WalkQuest أثناء الاتصال بالإنترنت وقم بإجراء المزامنة مرة أخرى.",
      "healthCheck4": "تحقق من التاريخ المحدد وتذكر أن إجمالي خطوات اليوم قد يتم تحديثه على دفعات.",
      "healthCheck5": "بعد إعادة تثبيت التطبيق، أعد الاتصال بـ Health Connect قبل توقع ظهور بيانات الخطوات القديمة.",
      "healthDistanceTitle": "لماذا لا تتطابق قيم الخطوات والكيلومترات؟",
      "healthDistanceP1": "يستخدم WalkQuest معادلة تحويل بسيطة خاصة باللعبة تعادل حوالي 1250 خطوة لكل كيلومتر افتراضي (قبل احتساب المكافآت وعوامل التعديل الأخرى). إنها مسافة تحفيزية داخل اللعبة، وليست قياساً طبياً لطول الخطوة.",
      "healthDistanceP2": "وهذا يعني أن تطبيقين قد يعرضان قيماً مختلفة للكيلومترات رغم اتفاقهما على نفس عدد الخطوات. بالنسبة لـ WalkQuest، يُعد إجمالي الخطوات هو المدخل الأهم، بينما تمثل مسافة المسار تفسير اللعبة لذلك الجهد المبذول.",
      "healthPrivacyTitle": "ما يقرؤه WalkQuest—وما لا يقرؤه",
      "healthPrivacyP1": "تقتصر صلاحية الوصول المطلوبة على معلومات الخطوات اللازمة لتتبع التقدم في المسار. لا يتطلب WalkQuest إنشاء حساب، ولا تُستخدم البيانات الصحية لإنشاء ملف تعريف إعلاني. يمكنك إلغاء صلاحية الوصول في أي وقت من خلال إعدادات Health Connect.",
      "healthQuote": "يجب أن يكون الاتصال سلساً وهادئاً: امنح الإذن مرة واحدة، وامشِ بشكل طبيعي، ودع خريطتك تروي القصة.",
