      "releaseTitle": "Um espaço maior para cada jornada no WalkQuest",
      "releaseLead": "O novo site do WalkQuest é mais do que uma simples página de apresentação: agora é um guia de campo multilíngue para entender o jogo antes mesmo de dar o primeiro passo.",
      "releaseDate": "1º de outubro de 2026",
      "releaseReadTime": "6 min de leitura",
      "releaseIntroP1": "Um jogo de caminhada pode ser simples de jogar e, ainda assim, conter um mundo inteiro de detalhes. O WalkQuest conecta passos, rotas, cidades, traslados, carimbos no passaporte, conquistas e opções Premium. O site reformulado reúne todos esses elementos em um ambiente tranquilo e organizado.",
      "releaseIntroP2": "O objetivo é prático: o visitante deve entender o que o WalkQuest faz em menos de um minuto, enquanto o viajante ativo pode encontrar informações mais detalhadas sem precisar navegar por vários menus.",
      "releaseLanguageTitle": "Dezesseis idiomas, uma jornada compartilhada",
      "releaseLanguageP1": "Todas as páginas principais e artigos seguem o idioma selecionado no site. Na primeira visita, o WalkQuest verifica o idioma do navegador;se for um idioma suportado, a página abre automaticamente nele. Caso contrário, o inglês é utilizado.",
      "releaseLanguageP2": "A escolha é salva no dispositivo e acompanha você desde o guia do jogo até as rotas, a versão Premium, a política de privacidade e o diário de bordo. No caso do árabe, a direção da leitura muda completamente para o sentido da direita para a esquerda.",
      "releaseCalloutTitle": "Por que isso é importante",
      "releaseCalloutText": "Um jogador que chega diretamente da Google Play pode ler a explicação, a política de privacidade e o material de suporte em um idioma familiar, sem precisar criar uma conta.",
