      "releasePathP1": "O site agora separa respostas rápidas de orientações detalhadas. A página inicial explica a proposta do jogo;o guia do jogo mostra os controles;o atlas de rotas ajuda a escolher um destino;e a página Premium explica as compras sem ocultar a experiência gratuita.",
      "releaseFeature1Title": "Guia do jogo",
      "releaseFeature1Text": "Veja como os passos movem o marcador, como as cidades são desbloqueadas e o que acontece em balsas, trens ou portões de embarque de voos.",
      "releaseFeature2Title": "Atlas de rotas",
      "releaseFeature2Text": "Compare aventuras curtas com jornadas épicas usando distâncias reais, paradas, níveis de dificuldade e número de traslados.",
      "releaseFeature3Title": "Diário",
      "releaseFeature3Text": "Leia histórias focadas em lançamentos, destinos e dicas práticas de configuração, em vez de anúncios de marketing vagos.",
      "releaseSameTitle": "O que não mudou",
