      "europeStatCountries": "países",
      "europeStatWeeksValue": "8 a 10 semanas",
      "europeStatWeeks": "jornada estimada",
      "europeIntroP1": "\"Europe Explorer\" é a rota que recomendamos quando alguém pergunta: \"Por onde devo começar?\"Ela é longa o suficiente para parecer uma verdadeira expedição, variada o bastante para manter o mapa interessante e disponível sem a necessidade de uma assinatura Premium.",
      "europeIntroP2": "A jornada começa em Londres e segue para o leste, em direção a Praga. Ao longo do caminho, cada cidade alcançada torna-se mais do que apenas um ponto no mapa: ela revela uma história, curiosidades locais, pontos turísticos, gastronomia, links de mapas e um novo carimbo no passaporte.",
      "europeWhyTitle": "Por que ela funciona como uma primeira rota",
      "europeWhyP1": "O nível de dificuldade \"Fácil\" não serve para fazer os quilômetros desaparecerem magicamente. Significa que a rota tem um ritmo agradável e um objetivo claro. Com uma média de 1. 250 passos por quilômetro virtual (antes dos bônus), até mesmo uma caminhada diária modesta gera um progresso visível.",
      "europeCalloutTitle": "Um ritmo adequado",
      "europeCalloutText": "Não tente chegar à linha de chegada logo no primeiro dia. Defina uma meta diária de caminhada que você consiga manter e deixe que as cidades surjam como recompensa pela sua constância.",
