      "europeStopsP2": "Quando uma parada for desbloqueada, faça uma pausa. Leia a breve introdução, conheça o ponto turístico, confira o Street View (quando disponível) e adicione o carimbo ao seu passaporte. Esse pequeno ritual é o que transforma a distância percorrida em uma verdadeira jornada.",
